 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find each 2x2 marker and rotate the four surrounding colors clockwise,
    # extending each color outward along its corner's diagonal.
    boxes = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                if not any(abs(r - br) <= 1 and abs(c - bc) <= 1 for br, bc in boxes):
                    boxes.append((r, c))
    for r, c in boxes:
        # Clockwise order: NW, NE, SE, SW. Each marker corner receives
        # the color from the preceding corner in that clockwise cycle.
        coords = [(r - 1, c - 1), (r - 1, c + 2), (r + 2, c + 2), (r + 2, c - 1)]
        colors = [grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0 for rr, cc in coords]
        dirs = [(-1, -1), (-1, 1), (1, 1), (1, -1)]
        for i, (rr, cc) in enumerate(coords):
            color = colors[(i - 1) % 4]
            dr, dc = dirs[i]
            y, x = rr, cc
            while 0 <= y < h and 0 <= x < w:
                out[y][x] = color
                y += dr
                x += dc
    return out
